package com.omer.belestiviclone

/** Exact display-only registry. Originals/provenance live in the dated logo evidence package.
 * Never use a screenshot crop as channel artwork. Channel/URI/database identity is unchanged.
 */
internal fun approvedLogo(name: String): String? = cleanLogoFiles[name]?.let { "clean-channel-logos/$it" }
internal fun forceLogoFallback(name: String): Boolean = name in quarantinedLogoUrls ||
    (name.startsWith("logo_") && name !in cleanLogoFiles)

